/**
 * Diamond Art Templates — Scripture-inspired designs.
 *
 * Each template is a 20×20 grid. Cells are colorIds (1..N) or 0 (empty/background).
 * Palette colorId 0 is reserved for "empty" and never selectable.
 *
 * Cell data is generated by small shape functions to keep this file readable.
 * Each template ends up as a flat array of length cols*rows.
 */

const COLS = 20;
const ROWS = 20;

// ── Helpers ────────────────────────────────────────────────────────────────
const idx = (r, c) => r * COLS + c;

function emptyCells() {
  return new Array(COLS * ROWS).fill(0);
}

function fillCircle(cells, cx, cy, radius, colorId) {
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      const d = Math.sqrt((c - cx) ** 2 + (r - cy) ** 2);
      if (d <= radius) cells[idx(r, c)] = colorId;
    }
  }
}

function fillRect(cells, r0, c0, r1, c1, colorId) {
  for (let r = r0; r <= r1; r++) {
    for (let c = c0; c <= c1; c++) {
      if (r >= 0 && r < ROWS && c >= 0 && c < COLS) cells[idx(r, c)] = colorId;
    }
  }
}

function setCell(cells, r, c, colorId) {
  if (r >= 0 && r < ROWS && c >= 0 && c < COLS) cells[idx(r, c)] = colorId;
}

// ── Template 1: Lilies of the Field ───────────────────────────────────────
function buildLilies() {
  const cells = emptyCells();
  // Sky background (top half soft cream)
  fillRect(cells, 0, 0, 11, COLS - 1, 1); // sky
  // Grass field bottom
  fillRect(cells, 12, 0, ROWS - 1, COLS - 1, 2); // grass
  // Three lily petals (cross-shape)
  // Center flower around (10, 10)
  // Petals — white (3)
  const petals = [
    [6, 10], [7, 9], [7, 10], [7, 11],
    [8, 8], [8, 9], [8, 10], [8, 11], [8, 12],
    [9, 7], [9, 8], [9, 12], [9, 13],
    [10, 7], [10, 13],
    [11, 8], [11, 9], [11, 11], [11, 12],
  ];
  petals.forEach(([r, c]) => setCell(cells, r, c, 3));
  // Center — gold (4)
  setCell(cells, 9, 10, 4);
  setCell(cells, 10, 9, 4);
  setCell(cells, 10, 10, 4);
  setCell(cells, 10, 11, 4);
  setCell(cells, 11, 10, 4);
  // Stem — green deeper (5)
  for (let r = 12; r <= 17; r++) setCell(cells, r, 10, 5);
  // Leaves — green deeper (5)
  setCell(cells, 14, 9, 5); setCell(cells, 14, 11, 5);
  setCell(cells, 15, 8, 5); setCell(cells, 15, 12, 5);
  // Smaller side blossoms — rose (6)
  setCell(cells, 13, 5, 6); setCell(cells, 14, 5, 6); setCell(cells, 13, 4, 6);
  setCell(cells, 13, 15, 6); setCell(cells, 14, 15, 6); setCell(cells, 13, 16, 6);
  return cells;
}

// ── Template 2: Stars in the Sky ──────────────────────────────────────────
function buildStars() {
  const cells = emptyCells();
  // Deep night sky everywhere
  fillRect(cells, 0, 0, ROWS - 1, COLS - 1, 1); // navy
  // Horizon hint at bottom — deeper navy (2)
  fillRect(cells, 17, 0, ROWS - 1, COLS - 1, 2);
  // Moon — top right crescent (3 light, 4 gold edge)
  fillCircle(cells, 15, 4, 3.5, 3);
  // Crescent cut
  fillCircle(cells, 13.5, 3.5, 3, 1);
  // Stars — bright gold (4)
  const stars = [
    [2, 3], [3, 7], [1, 11], [4, 15], [6, 5],
    [7, 13], [9, 17], [10, 3], [11, 9], [13, 7],
    [14, 13], [15, 16], [8, 8],
  ];
  stars.forEach(([r, c]) => setCell(cells, r, c, 4));
  // Star sparkles — cream (5)
  stars.forEach(([r, c]) => {
    setCell(cells, r - 1, c, 5);
    setCell(cells, r + 1, c, 5);
    setCell(cells, r, c - 1, 5);
    setCell(cells, r, c + 1, 5);
  });
  // Restore star centers
  stars.forEach(([r, c]) => setCell(cells, r, c, 4));
  return cells;
}

// ── Template 3: Mountains ─────────────────────────────────────────────────
function buildMountains() {
  const cells = emptyCells();
  // Sky gradient top — peach (1)
  fillRect(cells, 0, 0, 5, COLS - 1, 1);
  // Sky — rose (2)
  fillRect(cells, 6, 0, 9, COLS - 1, 2);
  // Distant mountains — lavender (3)
  for (let c = 0; c < COLS; c++) {
    const h = Math.round(4 + 2 * Math.sin(c * 0.7));
    for (let r = 10 - h; r <= 12; r++) {
      if (r >= 0) setCell(cells, r, c, 3);
    }
  }
  // Foreground mountains — deep blue (4)
  for (let c = 0; c < COLS; c++) {
    const h = Math.round(5 + 3 * Math.sin(c * 0.5 + 1));
    for (let r = 14 - h; r <= 16; r++) {
      if (r >= 0) setCell(cells, r, c, 4);
    }
  }
  // Snow caps — cream (5)
  for (let c = 0; c < COLS; c++) {
    const h = Math.round(5 + 3 * Math.sin(c * 0.5 + 1));
    const peakRow = 14 - h;
    if (peakRow >= 0) setCell(cells, peakRow, c, 5);
  }
  // Sun — gold (6)
  fillCircle(cells, 14, 4, 2, 6);
  // Lake bottom — blue (4) reflective
  fillRect(cells, 17, 0, ROWS - 1, COLS - 1, 4);
  return cells;
}

// ── Template 4: Dove with Olive Branch ────────────────────────────────────
function buildDove() {
  const cells = emptyCells();
  // Soft sky background (1)
  fillRect(cells, 0, 0, ROWS - 1, COLS - 1, 1);
  // Dove body — white (2)
  // Body oval
  const bodyPts = [
    [9, 8], [9, 9], [9, 10], [9, 11], [9, 12],
    [10, 7], [10, 8], [10, 9], [10, 10], [10, 11], [10, 12], [10, 13],
    [11, 7], [11, 8], [11, 9], [11, 10], [11, 11], [11, 12], [11, 13],
    [12, 8], [12, 9], [12, 10], [12, 11], [12, 12],
  ];
  bodyPts.forEach(([r, c]) => setCell(cells, r, c, 2));
  // Head — white
  setCell(cells, 8, 13, 2); setCell(cells, 8, 14, 2);
  setCell(cells, 9, 13, 2); setCell(cells, 9, 14, 2);
  // Beak — gold (3)
  setCell(cells, 9, 15, 3);
  // Eye — dark (4)
  setCell(cells, 8, 14, 4);
  // Wing — pale grey (5)
  setCell(cells, 8, 9, 5); setCell(cells, 8, 10, 5); setCell(cells, 8, 11, 5);
  setCell(cells, 7, 10, 5); setCell(cells, 7, 11, 5);
  // Tail
  setCell(cells, 10, 6, 2); setCell(cells, 11, 6, 2); setCell(cells, 12, 7, 2);
  // Olive branch — green (6)
  setCell(cells, 11, 14, 6); setCell(cells, 11, 15, 6); setCell(cells, 11, 16, 6);
  setCell(cells, 10, 16, 6); setCell(cells, 12, 15, 6); setCell(cells, 10, 14, 6);
  // Olives — gold (3)
  setCell(cells, 10, 17, 3); setCell(cells, 12, 16, 3);
  return cells;
}

// ── Template 5: Light of the World (Lantern) ──────────────────────────────
function buildLight() {
  const cells = emptyCells();
  // Dark room (1)
  fillRect(cells, 0, 0, ROWS - 1, COLS - 1, 1);
  // Glow halo — soft gold (2)
  fillCircle(cells, 10, 10, 7, 2);
  // Inner glow — bright gold (3)
  fillCircle(cells, 10, 10, 4, 3);
  // Lantern body outline — brass (4)
  // Top cap
  fillRect(cells, 5, 8, 5, 12, 4);
  setCell(cells, 4, 9, 4); setCell(cells, 4, 10, 4); setCell(cells, 4, 11, 4);
  // Frame
  for (let r = 6; r <= 14; r++) {
    setCell(cells, r, 7, 4);
    setCell(cells, r, 13, 4);
  }
  // Base
  fillRect(cells, 15, 7, 15, 13, 4);
  setCell(cells, 16, 9, 4); setCell(cells, 16, 10, 4); setCell(cells, 16, 11, 4);
  // Flame inside — white-hot center (5)
  setCell(cells, 9, 10, 5);
  setCell(cells, 10, 10, 5);
  setCell(cells, 11, 10, 5);
  // Hanging chain — brass (4)
  setCell(cells, 3, 10, 4); setCell(cells, 2, 10, 4); setCell(cells, 1, 10, 4);
  return cells;
}

// ── Template 6: Clean Heart ──────────────────────────────────────────────
function buildHeart() {
  const cells = emptyCells();
  // Cream background (1)
  fillRect(cells, 0, 0, ROWS - 1, COLS - 1, 1);
  // Heart shape — rose (2)
  // Use parametric heart inequality (approx)
  for (let r = 2; r < ROWS - 2; r++) {
    for (let c = 2; c < COLS - 2; c++) {
      const x = (c - 9.5) / 6;
      const y = -(r - 10) / 6;
      // Heart curve: (x^2 + y^2 - 1)^3 - x^2 * y^3 <= 0
      const v = Math.pow(x * x + y * y - 1, 3) - x * x * Math.pow(y, 3);
      if (v <= 0) setCell(cells, r, c, 2);
    }
  }
  // Inner highlight — pink (3)
  for (let r = 2; r < ROWS - 2; r++) {
    for (let c = 2; c < COLS - 2; c++) {
      const x = (c - 9.5) / 6;
      const y = -(r - 10) / 6;
      const v = Math.pow(x * x + y * y - 1, 3) - x * x * Math.pow(y, 3);
      if (v <= -0.4) setCell(cells, r, c, 3);
    }
  }
  // Shine spot — white (4)
  setCell(cells, 7, 7, 4); setCell(cells, 7, 8, 4); setCell(cells, 8, 7, 4);
  // Tiny stars around — gold (5)
  setCell(cells, 3, 3, 5); setCell(cells, 3, 16, 5);
  setCell(cells, 16, 3, 5); setCell(cells, 16, 16, 5);
  return cells;
}

